<?php
declare(strict_types=1);
require __DIR__.'/config/bootstrap.php';
$user=require_auth();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM projects WHERE id=? AND ownerId=?');$s->execute([$id,$user['id']]);$project=$s->fetch();if(!$project)redirect('dashboard.php');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';if($action==='category'){$name=trim($_POST['name']??'');if($name){$q=$pdo->prepare('INSERT INTO estimatecategories(projectId,name) VALUES(?,?)');$q->execute([$id,$name]);}redirect('project.php?id='.$id);}if($action==='item'){$cat=(int)($_POST['category_id']??0);$q=$pdo->prepare('SELECT id FROM estimatecategories WHERE id=? AND projectId=?');$q->execute([$cat,$id]);if($q->fetch()){$name=trim($_POST['name']??'');$qty=(float)str_replace(',','.',$_POST['quantity']??0);$unit=trim($_POST['unit']??'шт.');$price=(float)str_replace(',','.',$_POST['price']??0);if($name!==''){$q=$pdo->prepare('INSERT INTO estimateitems(categoryId,name,quantity,unit,price,source) VALUES(?,?,?,?,?,?)');$q->execute([$cat,$name,$qty,$unit,$price,'manual']);}}redirect('project.php?id='.$id);}if($action==='delete_item'){$q=$pdo->prepare('DELETE i FROM estimateitems i JOIN estimatecategories c ON c.id=i.categoryId WHERE i.id=? AND c.projectId=?');$q->execute([(int)$_POST['item_id'],$id]);redirect('project.php?id='.$id);}if($action==='delete_project'){$q=$pdo->prepare('DELETE FROM projects WHERE id=? AND ownerId=?');$q->execute([$id,$user['id']]);redirect('dashboard.php');}}
$q=$pdo->prepare('SELECT c.*,COALESCE(SUM(i.quantity*i.price),0) total FROM estimatecategories c LEFT JOIN estimateitems i ON i.categoryId=c.id WHERE c.projectId=? GROUP BY c.id ORDER BY c.sortOrder,c.id');$q->execute([$id]);$cats=$q->fetchAll();$total=0;foreach($cats as &$cat){$q=$pdo->prepare('SELECT * FROM estimateitems WHERE categoryId=? ORDER BY id');$q->execute([$cat['id']]);$cat['items']=$q->fetchAll();$total+=(float)$cat['total'];}unset($cat);
$pageTitle=$project['name'];require __DIR__.'/includes/header.php';?>
<div class="app-page"><div class="container"><div class="page-head"><div><a href="dashboard.php" class="back-link">← Проекты</a><h1><?=e($project['name'])?></h1><p class="text-muted mb-0"><?=e(($project['city']??'').(($project['clientName']??'')?' · '.$project['clientName']:''))?></p></div><div class="d-flex gap-2"><button class="btn btn-light" data-bs-toggle="modal" data-bs-target="#categoryModal">+ Раздел</button><button class="btn btn-outline-danger" data-confirm="Удалить проект и всю смету?" onclick="document.getElementById('deleteProjectForm').submit()">Удалить</button></div></div><?php foreach($cats as $cat):?><section class="estimate-section surface"><div class="section-head"><div><div class="eyebrow">РАЗДЕЛ</div><h2><?=e($cat['name'])?></h2></div><button class="btn btn-primary btn-sm" data-bs-toggle="modal" data-bs-target="#item<?=$cat['id']?>">+ Добавить позицию</button></div><div class="table-responsive"><table class="table estimate-table align-middle mb-0"><thead><tr><th>Наименование</th><th>Кол-во</th><th>Ед.</th><th>Цена</th><th class="text-end">Сумма</th><th></th></tr></thead><tbody><?php foreach($cat['items'] as $item):$sum=(float)$item['quantity']*(float)$item['price'];?><tr><td><strong><?=e($item['name'])?></strong></td><td><?=rtrim(rtrim(number_format((float)$item['quantity'],3,',',' '),'0'),',')?></td><td><?=e($item['unit'])?></td><td><?=number_format((float)$item['price'],2,',',' ')?> ₽</td><td class="text-end fw-semibold"><?=number_format($sum,2,',',' ')?> ₽</td><td class="text-end"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_item"><input type="hidden" name="item_id" value="<?=$item['id']?>"><button class="btn btn-sm btn-link text-danger">Удалить</button></form></td></tr><?php endforeach;?><?php if(!$cat['items']):?><tr><td colspan="6" class="text-center text-muted py-4">В разделе пока нет позиций.</td></tr><?php endif;?></tbody></table></div></section><div class="modal fade" id="item<?=$cat['id']?>" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title">Новая позиция</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="item"><input type="hidden" name="category_id" value="<?=$cat['id']?>"><label class="form-label">Наименование</label><input class="form-control form-control-lg mb-3" name="name" required><div class="row g-3"><div class="col-4"><label class="form-label">Кол-во</label><input class="form-control" name="quantity" value="1"></div><div class="col-4"><label class="form-label">Ед.</label><input class="form-control" name="unit" value="шт."></div><div class="col-4"><label class="form-label">Цена</label><input class="form-control" name="price" data-money value="0"></div></div></div><div class="modal-footer"><button class="btn btn-primary">Добавить</button></div></form></div></div></div><?php endforeach;?><?php if(!$cats):?><div class="empty-state surface"><div class="feature-icon">01</div><h3>Создайте первый раздел</h3><p>Например: «Материалы», «Работы» или «Техника».</p><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#categoryModal">Добавить раздел</button></div><?php endif;?><div class="total-box surface"><span>Итого по проекту</span><strong><?=number_format($total,2,',',' ')?> ₽</strong></div></div></div><div class="modal fade" id="categoryModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title">Новый раздел</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="category"><label class="form-label">Название</label><input class="form-control form-control-lg" name="name" required placeholder="Материалы"></div><div class="modal-footer"><button class="btn btn-primary">Создать</button></div></form></div></div></div><form id="deleteProjectForm" method="post" class="d-none"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_project"></form>
<?php require __DIR__.'/includes/footer.php';?>